import { Button } from '@carbon/react'
import { Close } from '@carbon/react/icons/index.js'
import classnames from 'classnames'
import PropTypes from 'prop-types'
import React from 'react'

export const IdeSlideOverPanel = ({
  open,
  title,
  onClose,
  children
}) => (
  <aside
    className={classnames({
      'ide-slide-over-panel': true,
      'ide-slide-over-panel--open': open
    })}
  >
    <header className='ide-slide-over-panel--header'>
      <h3 className='ide-slide-over-panel--h3'>{title}</h3>
      <Button
        disabled={false}
        hasIconOnly
        iconDescription='Close'
        kind='ghost'
        onClick={onClose}
        renderIcon={Close}
        tooltipAlignment='center'
        tooltipPosition='bottom'
        type='button'
      />
    </header>
    <div className='ide-slide-over-panel--children'>
      {children}
    </div>
  </aside>
)

IdeSlideOverPanel.propTypes = {
  children: PropTypes.node,
  onClose: PropTypes.func.isRequired,
  open: PropTypes.bool.isRequired,
  title: PropTypes.string
}
