export const REPO_METADATA_URL = 'https://ot4i.github.io/ace-tutorials/v13/en/repo_metadata.json'
export const PATTERNS_REPO_METADATA_URL = 'https://ot4i.github.io/ace-tutorials/v13/en/patterns_repo_metadata.json'

const VERSION_NUMBER = 13

// Function that returns patterns for a specified version
export const fetchItemsForVersion = items =>
  items.filter(item => {
    // `item.iibVersions` is e.g. "13.*-13.*"
    const [fromValue, toValue] = item.iibVersions.split('-').map(v => Number.parseInt(v.split('.')[0]))
    return fromValue <= VERSION_NUMBER && VERSION_NUMBER <= toValue
  })
