/*
This javascript file is for the main tutorials page which lists all the tutorials and has promoted tutoroials at the top of the page.
The search capability is also in this file. It uses IdeFilter.
*/

// cp4i update
import { ClickableTile } from '@carbon/react'
import { Time } from '@carbon/react/icons/index.js'
import PropTypes from 'prop-types'
import React, { useEffect, useState } from 'react'

import integrationServerImg from '../../../assets/integration-server.svg'
import messageFlowImg from '../../../assets/message-flow.svg'
import restApiImg from '../../../assets/rest-api.svg'
import repoMetadata from '../../../repo_metadata.json'
import allTutorials from '../../../tutorials_data.json'
import { REPO_METADATA_URL, fetchItemsForVersion } from '../../../utils/misc.js'
import { ListPanelItem } from '../../ListPanelItem/ListPanelItem.jsx'
import { Tutorial } from '../../Tutorial/Tutorial.jsx'
import { IdeFilter } from '../../cdai/IdeFilter/IdeFilter.jsx'
import { IdePage } from '../../cdai/IdePage/IdePage.jsx'
import { IdeSlideOverPanel } from '../../cdai/IdeSlideOverPanel/IdeSlideOverPanel.jsx'

const startTutorial = (e, tutorialData) => {
  e.preventDefault()
  e.stopPropagation()

  if (!tutorialData) {
    return
  }

  const currentWindowHref = window.location.href
  // We'll use the current location to ease testing.
  // Main URL was 'https://ot4i.github.io/ace-tutorials/v12/en/#/./tutorials/'
  const tutorialsPageUrl = currentWindowHref + '/'

  const selectedTutorialUrl = tutorialData.stepsURL
  const selectedTutorialUrlSplit = selectedTutorialUrl.split('/')
  const tutorialRepoName = selectedTutorialUrlSplit[9]

  try {
    window.javaSetSelectedTutorialFunction(tutorialData.name)
  } catch (e) {
    window.alert('a java error in javaSetSelectedTutorialFunction occurred: ' + e.message)
  }

  try {
    window.javaOpenTutorialStepsFunction(tutorialsPageUrl + tutorialRepoName)
  } catch (e) {
    window.alert('a java error in javaOpenTutorialStepsFunction occurred: ' + e.message)
  }
}

const TutorialsListItems = ({ search, handleClick, tutorialsData }) => {
  const tutorials = (tutorialsData && tutorialsData.categories[0].tutorials) || repoMetadata.categories[0].tutorials.slice()

  // Pass in list of tutorials and version number
  const v13Tutorials = fetchItemsForVersion(tutorials)

  const filterRegex = new RegExp(search, 'i')
  const filterFunc = item =>
    filterRegex.exec(item.name) !== null ||
    filterRegex.exec(item.tags) !== null ||
    filterRegex.exec(item.category) !== null

  const list = v13Tutorials.filter(filterFunc)

  const listDom = []

  let updatedList = list

  if (!search) {
    const removedItems = list.splice(0, 3)
    updatedList = list.concat(removedItems)
  }

  for (const item of updatedList) {
    const _tags = item.tags ? item.tags.split(';') : []
    const _categories = item.category ? item.category.split(',') : []

    listDom.push(
      <ListPanelItem
        name={item.name}
        desc={item.shortDesc}
        tags={_tags.concat(_categories)}
        key={item.name}
        handleLinkClick={() => handleClick(item.name, false)}
        startTutorial={e => startTutorial(e, item)}
      />
    )
  }

  return (
    <ul className='tutorials-list-items'>
      {listDom}
    </ul>
  )
}

TutorialsListItems.propTypes = {
  search: PropTypes.string.isRequired,
  handleClick: PropTypes.func.isRequired,
  tutorialsData: PropTypes.any
}

const PromotedTutorial = ({ name, image, durationMins, handleClick }) => {
  let imgSource
  if (image === 'integration-server') {
    imgSource = integrationServerImg
  } else if (image === 'message-flow') {
    imgSource = messageFlowImg
  } else {
    imgSource = restApiImg
  }

  return (
    <ClickableTile
      onClick={() => handleClick(name)}
      className='promoted-tutorial__tile'
      tabIndex='0'
    >
      <p className='promoted-tutorial__text'>
        {name}
      </p>
      <div className='promoted-tutorial__lower'>
        <img src={imgSource} className='promoted-tutorial__img' alt='Tutorial' />
        <div className='promoted-tutorial__duration'>
          <Time size={16} aria-label='Timing indicator' />
          <span>
            {durationMins}
          </span>
        </div>
      </div>
    </ClickableTile>
  )
}

PromotedTutorial.propTypes = {
  name: PropTypes.node,
  image: PropTypes.string.isRequired,
  durationMins: PropTypes.node,
  handleClick: PropTypes.func
}

const PromotedTutorials = ({ handleClick, tutorialsData }) => {
  const list = []
  const tutorials = (tutorialsData && tutorialsData.categories[0].tutorials) || repoMetadata.categories[0].tutorials.slice()
  const v13Tutorials = fetchItemsForVersion(tutorials)

  for (let i = 0; i < 3; i++) {
    const tutorialDuration = allTutorials[v13Tutorials[i].name] && allTutorials[v13Tutorials[i].name].tutorial._common.durationTime
    v13Tutorials[i].durationMins = tutorialDuration
    if (v13Tutorials[i].name.toLowerCase().includes('integration')) {
      v13Tutorials[i].image = 'integration-server'
    } else if (tutorials[i].name.toLowerCase().includes('message')) {
      v13Tutorials[i].image = 'message-flow'
    } else {
      v13Tutorials[i].image = 'rest-api'
    }
    list.push(v13Tutorials[i])
  }

  const listDom = []

  for (const item of list) {
    listDom.push(
      <PromotedTutorial
        name={item.name}
        image={item.image}
        key={item.name}
        handleClick={handleClick}
        durationMins={item.durationMins}
      />
    )
  }

  return (
    <ul className='promoted-tutorials'>
      {listDom}
    </ul>
  )
}

PromotedTutorials.propTypes = {
  handleClick: PropTypes.func.isRequired,
  tutorialsData: PropTypes.any
}

const v13Tutorials = fetchItemsForVersion(repoMetadata.categories[0].tutorials)
const colours = [
  'red',
  'magenta',
  'purple',
  'blue',
  'cyan',
  'teal',
  'green',
  'gray',
  'cool-gray',
  'warm-gray'
]
const allTags = new Set()

for (const item of v13Tutorials) {
  const tags = (item.tags && item.tags.split(';')) || []
  const categories = (item.category && item.category.split(',')) || []

  for (const tag of tags) {
    allTags.add(tag)
  }

  for (const cat of categories) {
    allTags.add(cat)
  }
}

const filterOptions = [{
  label: 'Tags',
  options: [...allTags].map(tag => ({
    type: colours[Math.floor(Math.random() * colours.length)],
    value: tag,
    label: tag
  }))
}]

export const TutorialsPage = () => {
  const [search, setSearch] = useState('')
  const [panelOpen, setPanelOpen] = useState(false)
  const [tutorialDetails, setTutorialDetails] = useState({})

  const handleStartTutorial = tutorialName => {
    // Uncomment next line for local development, so that we can navigate to a specific tutorial by clicking start
    // history.push(`/tutorials/${tutorialName}${route.location.search}`)
  }

  // This causes the overview to be shown on the right hand side.
  const handleTutorialClick = tutorialName => {
    setPanelOpen(true)
    setTutorialDetails({ title: tutorialName })
  }

  const handleClose = () => {
    setPanelOpen(false)
    setTutorialDetails({})
  }

  const handleFilterChange = val => {
    if (val) {
      const valMap = val.map(item => item.value)
      setSearch(`((${valMap.join(')|(')}))`)
    } else {
      setSearch('')
    }
  }

  // Fetches latest repo_metadata from public Github
  const [tutorialsData, setTutorialsData] = useState(null)
  useEffect(() => {
    // eslint-disable-next-line no-unused-vars
    const fetchTutorialsData = async () => {
      const response = await fetch(REPO_METADATA_URL, {
        headers: new Headers({
          Accept: 'application/vnd.github.v3+json'
        }),
        method: 'GET',
        mode: 'cors',
        credentials: 'omit' // Useful for including session ID (and, IIRC, authorization headers)
      })

      const responseData = await response.json()
      if (responseData) {
        setTutorialsData(responseData)
      }
    }
    // Uncomment next line if you want to use a local dev version of repo_metadata.json
    // fetchTutorialsData()
  }, [])

  return (
    <IdePage heading='Tutorials'>
      <div className='tutorials'>
        <IdeFilter
          options={filterOptions}
          onChange={handleFilterChange}
        />
        {search.length === 0 && (
          <PromotedTutorials
            handleClick={handleTutorialClick}
            tutorialsData={tutorialsData}
          />
        )}
        <TutorialsListItems
          search={search}
          handleClick={handleTutorialClick}
          tutorialsData={tutorialsData}
        />
      </div>
      <IdeSlideOverPanel
        open={panelOpen}
        onClose={handleClose}
        title={tutorialDetails.title}
      >
        <Tutorial
          name={tutorialDetails.title}
          handleLinkClick={handleStartTutorial}
          tutorialsData={tutorialsData}
        />
      </IdeSlideOverPanel>
    </IdePage>
  )
}
