/*
  Contains code that displays the Overview for a single Tutorial within TutorialsPage
*/

import { UnorderedList, ListItem } from '@carbon/react'
import { Time, Download } from '@carbon/react/icons/index.js'
import PropTypes from 'prop-types'
import React from 'react'

import allTutorials from '../../tutorials_data.json'

export const TutorialPreview = ({ tutorialName, downloadCount, tutorialData }) => {
  const tutorialDataLength = tutorialData && Object.keys(tutorialData).length
  const tutorial = tutorialDataLength > 0 ? tutorialData : allTutorials[tutorialName]
  const details = (tutorial && tutorial.tutorial && tutorial.tutorial.pageDetails) || {}
  const common = (tutorial && tutorial.tutorial && tutorial.tutorial._common) || {}
  const summary = details && details.summary

  return (
    <div className='tutorial-preview'>
      <p className='tutorial-preview__text'>
        {common && common.shortDescription}
      </p>
      <div className='tutorial-preview__schedule-container'>
        <div className='tutorial-preview__schedule' title='Estimated tutorial duration time'>
          <Time size={20} className='tutorial-preview__icon' />
          <p>{common && common.durationTime}.</p>
        </div>
        {downloadCount && (
          <div className='tutorial-preview__downloads' title='Number of downloads'>
            <Download size={20} className='tutorial-preview__icon' />
            <p>{downloadCount}</p>
          </div>
        )}
      </div>
      <div>
        <p className='tutorial-preview__text-header'>
          {details && details.topicsName}
        </p>
        {details && details.topicList && (
          <UnorderedList className='tutorial-preview__list'>
            {details.topicList.map(topic => (
              <ListItem key={topic.title}>
                {topic.title}
              </ListItem>
            ))}
          </UnorderedList>
        )}
      </div>
      <div>
        <p className='tutorial-preview__text-header'>
          {details && details.outcomesName}
        </p>
        {details && details.outcomeList && (
          <UnorderedList className='tutorial-preview__list'>
            {details.outcomeList.map(outcome => (
              <ListItem key={outcome.title}>
                {outcome.title}
              </ListItem>
            ))}
          </UnorderedList>
        )}
      </div>
      <div>
        <p className='tutorial-preview__text-header'>
          {summary && summary.overviewName && 'Overview'}
        </p>
        {summary && summary.sections && summary.sections.map((item, index) => (
          <p key={`item-section:${index}`} className='tutorial-preview__text'>
            {item && item.section}
          </p>
        ))}
      </div>
    </div>
  )
}

TutorialPreview.propTypes = {
  tutorialName: PropTypes.string,
  downloadCount: PropTypes.number,
  tutorialData: PropTypes.object
}
