/*
This javascript file is used by Page/TutorialsPage.js
This file has the java methods for the Tutorials page
This file is located within the TutorialsPage and contains code that displays the Details
popup for each Tutorial on the right.

The following callback funtions are registered by a toolkit plugin :

/com.ibm.etools.mft.tutorials/src/com/ibm/etools/mft/tutorials/views/TutorialManager.java
/com.ibm.etools.mft.tutorials/src/com/ibm/etools/mft/tutorials/views/TutorialStepsView.java

Callback functions:
javaSetSelectedTutorialFunction
javaOpenTutorialStepsFunction

*/

import { Button } from '@carbon/react'
import PropTypes from 'prop-types'
import React, { useEffect, useState } from 'react'

import repoMetadata from '../../repo_metadata.json'
import { TutorialPreview } from '../TutorialPreview/TutorialPreview.jsx'

const repoUrl = 'https://ot4i.github.io/'
const fileUrl = '/v12/en/data.json'
const githubApiUrl = 'https://api.github.com/repos/ot4i/'

const setSelectedTutorial = selectName => {
  try {
    window.javaSetSelectedTutorialFunction(selectName)
  } catch (e) {
    window.alert('a java error in javaSetSelectedTutorialFunction occurred: ' + e.message)
  }
}

const getTutorialData = (
  repoMetadataTutorial,
  handleLinkClick
) => {
  const stepsUrl = repoMetadataTutorial.stepsURL
  const tutorialStepsUrl = stepsUrl && stepsUrl.split('/')
  const tutorialName = tutorialStepsUrl[9]

  handleLinkClick(tutorialName)
}

const startTutorial = (
  tutorialName,
  handleLinkClick,
  tutorialsData
) => {
  const currentWindowHref = window.location.href
  // We'll use the current location to ease testing.
  // Main URL was 'https://ot4i.github.io/ace-tutorials/v12/en/#/./tutorials/'
  const tutorialsPageUrl = currentWindowHref + '/'

  if (tutorialName) {
    const fetchedTutorialsData = tutorialsData && tutorialsData.categories && tutorialsData.categories[0] && tutorialsData.categories[0].tutorials
    const foundTutorialsData = fetchedTutorialsData && fetchedTutorialsData.find(({ name }) => name === tutorialName)
    const repoMetadataTutorial = foundTutorialsData || repoMetadata.categories[0].tutorials.find(({ name }) => name === tutorialName)
    getTutorialData(repoMetadataTutorial, handleLinkClick)

    const selectedTutorialUrl = repoMetadataTutorial.stepsURL
    const selectedTutorialUrlSplit = selectedTutorialUrl.split('/')
    const tutorialRepoName = selectedTutorialUrlSplit[9]

    try {
      window.javaOpenTutorialStepsFunction(tutorialsPageUrl + tutorialRepoName)
    } catch (e) {
      window.alert('a java error in javaOpenTutorialStepsFunction occurred: ' + e.message)
    }
  }
}

export const Tutorial = ({ name, handleLinkClick, tutorialsData }) => {
  const tutorialName = name || ''

  useEffect(() => {
    setSelectedTutorial(tutorialName)
  }, [tutorialName])

  const fetchedTutorialsData = tutorialsData && tutorialsData.categories && tutorialsData.categories[0] && tutorialsData.categories[0].tutorials
  const foundTutorialsData = fetchedTutorialsData && fetchedTutorialsData.find(({ name }) => name === tutorialName)
  const repoMetadataTutorial = foundTutorialsData || repoMetadata.categories[0].tutorials.find(({ name }) => name === tutorialName)
  const tutorialZipUrl = repoMetadataTutorial && repoMetadataTutorial.zipURL ? repoMetadataTutorial.zipURL : null
  const repoName = repoMetadataTutorial && repoMetadataTutorial.stepsURL && repoMetadataTutorial.stepsURL.split('/')[9]

  const [downloadCount, setDownloadCount] = useState(null)

  const tutorialZipUrlArray = tutorialZipUrl && tutorialZipUrl.split('/')
  const zipUrlTutorialName = tutorialZipUrlArray && tutorialZipUrlArray[4]
  const zipUrlTutorialVersion = tutorialZipUrlArray && tutorialZipUrlArray[7]
  const zipUrlTutorialFile = tutorialZipUrlArray && tutorialZipUrlArray[8]

  let downloadCountUrl = ''
  if (zipUrlTutorialName && zipUrlTutorialVersion && zipUrlTutorialFile) {
    downloadCountUrl = githubApiUrl + zipUrlTutorialName + '/releases/tags/' + zipUrlTutorialVersion
  }

  // Fetches latest tutorial data for a single tutorial so that Overview displays
  const [tutorialData, setTutorialData] = useState(null)
  useEffect(() => {
    const fetchTutorialData = async () => {
      if (repoName && (repoName !== '')) {
        const response = await fetch(repoUrl + repoName + fileUrl, {
          headers: new Headers({
            Accept: 'application/vnd.github.v3+json'
          }),
          method: 'GET',
          mode: 'cors',
          credentials: 'omit' // Useful for including session ID (and, IIRC, authorization headers)
        })

        if (response.ok) {
          const responseData = await response.json()
          setTutorialData(responseData)
        } else {
          setTutorialData({})
        }
      }
    }
    fetchTutorialData()
  }, [repoName])

  // Fetches downloadCount for number of ZIP downloads
  useEffect(() => {
    const fetchDownloadCount = async () => {
      if (downloadCountUrl && (downloadCountUrl !== '')) {
        const response = await fetch(downloadCountUrl, {
          headers: new Headers({
            Accept: 'application/vnd.github.v3+json'
          }),
          method: 'GET',
          mode: 'cors',
          credentials: 'omit' // Useful for including session ID (and, IIRC, authorization headers)
        })

        const responseData = await response.json()
        if (responseData && responseData.assets[0] && responseData.assets[0].download_count) {
          setDownloadCount(responseData.assets[0].download_count)
        }
      } else {
        setDownloadCount(null)
      }
    }
    fetchDownloadCount()
  }, [downloadCountUrl])

  return (
    <div className='tutorial'>
      <div className='tutorial__preview'>
        <TutorialPreview
          tutorialName={tutorialName}
          downloadCount={downloadCount}
          tutorialData={tutorialData}
        />
      </div>
      <Button
        className='tutorial__start'
        onClick={() => startTutorial(tutorialName, handleLinkClick, tutorialsData)}
      >
        Start
      </Button>
    </div>
  )
}

Tutorial.propTypes = {
  name: PropTypes.string,
  handleLinkClick: PropTypes.func.isRequired,
  tutorialsData: PropTypes.shape({
    categories: PropTypes.arrayOf(PropTypes.shape({
      tutorials: PropTypes.arrayOf(PropTypes.shape({
        name: PropTypes.string
      }))
    }))
  })
}
